      "gu": "અર્જુન પ્રભુ કૃષ્ણને વિનંતી કરે છે કારણ કે તે ઈચ્છે છે કે તે તેમના અવિનાશી અને દિવ્ય સ્વરૂપને જુએ. તે સમજે છે કે આ સ્વરૂપને જોવાનું તેના માટે શક્ય છે કે નહીં તે પ્રભુની ઇચ્છા પર નિર્ભર છે.",
