      "te": "దీవించిన భగవంతుడు ఇలా అన్నాడు, \"ఓ అర్జునా, నా రూపాలు, వందల మరియు వేల, వివిధ రకాల, దివ్యమైన మరియు వివిధ రంగులు మరియు ఆకారాలు.\"",
