      "gu": "માં, આ દર્શન વિશે અર્જુન વાત કરી રહ્યા છે. તેઓ ભગવાન શ્રીકૃષ્ણના વિશ્વરૂપ દર્શનનો અનુભવ કરી રહ્યા છે અને તે માં તમામ દેવો, ભૂત, બ્રહ્મા, મહાદેવ, ઋષિઓ અને દૈવી સર્પોને જોઈ રહ્યા છે.",
