      "gu": "માં કૃષ્ણના રૂપને અત્યંત તેજસ્વી અને દિવ્ય રૂપમાં વર્ણવવામાં આવ્યું છે. તેઓને મુગટ, ગદા અને ચક્ર સાથે દર્શાવવામાં આવ્યા છે. તેઓનો તેજ પ્રજ્વલિત અગ્નિ અને સૂર્યની જેમ છે, અને તે દરેક દિશામાં પ્રકાશિત થાય છે.",
