    "teluguMeaning": "మీరు నాశనమైనవారు, సర్వోన్నతమైనవారు, గుర్తించబడటానికి అర్హులు. మీరు ఈ విశ్వం యొక్క గొప్ప నిధివి; నీవు శాశ్వతమైన ధర్మానికి నాశనమైన రక్షకుడివి; మీరు ప్రాథమిక వ్యక్తి, నేను నమ్ముతున్నాను.",
    "iast": "tvam akṣharaṁ paramaṁ veditavyaṁ\ntvam asya viśhvasya paraṁ nidhānam\ntvam avyayaḥ śhāśhvata-dharma-goptā\nsanātanas tvaṁ puruṣho mato me",
    "translations": {
      "en": "You are the Imperishable, the Supreme Being, worthy of being known. You are the great treasure-house of this universe; You are the imperishable protector of the eternal Dharma; You are the Primal Person, I believe.",
      "te": "మీరు నాశనమైనవారు, సర్వోన్నతమైనవారు, గుర్తించబడటానికి అర్హులు. మీరు ఈ విశ్వం యొక్క గొప్ప నిధివి; నీవు శాశ్వతమైన ధర్మానికి నాశనమైన రక్షకుడివి; మీరు ప్రాథమిక వ్యక్తి, నేను నమ్ముతున్నాను.",
      "hi": "आप ही जाननेयोग्य परम अक्षर (अक्षरब्रह्म) हैं, आप ही इस सम्पूर्ण विश्वके परम आश्रय हैं, आप ही सनातनधर्मके रक्षक हैं और आप ही अविनाशी सनातन पुरुष हैं -- ऐसा मैं मानता हूँ।",
      "sa": "त्वमक्षरं परमं वेदितव्यं\n\nत्वमस्य विश्वस्य परं निधानम्।\n\nत्वमव्ययः शाश्वतधर्मगोप्ता\n\nसनातनस्त्वं पुरुषो मतो मे।।11.18।।",
      "gu": "શ્લોકમાં ભગવાન કૃષ્ણને 'પરમ અક્ષર', 'પરમ નિધાન', 'અવ્યય' અને 'શાશ્વતધર્મગોપ્તા' તરીકે વર્ણવવામાં આવ્યા છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "आप ही जाननेयोग्य परम अक्षर (अक्षरब्रह्म) हैं, आप ही इस सम्पूर्ण विश्वके परम आश्रय हैं, आप ही सनातनधर्मके रक्षक हैं और आप ही अविनाशी सनातन पुरुष हैं -- ऐसा मैं मानता हूँ।",
