      "gu": "માં કહેવામાં આવ્યું છે કે દેવતાઓના સમૂહોએ ભગવાનના ગુણોનું ઉચ્ચારણ કર્યું છે. તેઓ ભયના કારણે હાથ જોડીને ભગવાનના નામો અને ગુણોની સ્તુતિ કરે છે.",
