      "te": "అనేక నోళ్లతో, కన్నులతో, అనేక బాహువులు, తొడలు మరియు పాదాలతో, అనేక కడుపులతో మరియు అనేక దంతాలతో భయంకరమైన నీ స్వరూపాన్ని చూసి, లోకులు భయపడుతున్నాయి, అలాగే నేను కూడా.",
      "hi": "हे महाबाहो! आपके बहुत मुखों और नेत्रोंवाले, बहुत भुजाओं, जंघाओं और चरणोंवाले, बहुत उदरोंवाले, बहुत विकराल दाढ़ोंवाले महान् रूपको देखकर सब प्राणी व्यथित हो रहे हैं तथा मैं भी व्यथित हो रहा हूँ।",
      "sa": "रूपं महत्ते बहुवक्त्रनेत्रं\n\nमहाबाहो बहुबाहूरुपादम्।\n\nबहूदरं बहुदंष्ट्राकरालं\n\nदृष्ट्वा लोकाः प्रव्यथितास्तथाऽहम्।।11.23।।",
      "gu": "માં ભગવાનનું બહુવક્ત્ર અને બહુનેત્રવાળું, બહુબાહુ અને બહુઉરુપદ્રમ્ રૂપ દર્શાવવામાં આવ્યું છે. આ રૂપમાં અનેક મુખો, આંખો, હાથ, જાંઘાં અને પગ જોવા મળે છે. આ ભયંકર અને વિશાળ રૂપને જોઈને સમગ્ર જગત ડરી ગયું છે, અને અર્જુન પણ ભયભીત છે.",
