    "teluguMeaning": "ఇంత భయంకరమైన రూపం కలిగిన నువ్వు ఎవరో చెప్పు. పరమేశ్వరుడా, నీకు నా నమస్కారాలు అర్పిస్తున్నాను; నన్ను కరుణించు. అసలు జీవి అయిన నిన్ను తెలుసుకోవాలని నేను కోరుకుంటున్నాను. మీ పని తీరు నాకు నిజంగా తెలియదు.",
    "iast": "ākhyāhi me ko bhavān ugra-rūpo\nnamo ’stu te deva-vara prasīda\nvijñātum ichchhāmi bhavantam ādyaṁ\nna hi prajānāmi tava pravṛittim",
    "translations": {
      "en": "Tell me, who you are, so fierce of form. I offer my salutations to you, O God Supreme; have mercy on me. I desire to know you, the original Being. I do not indeed know your workings.",
      "te": "ఇంత భయంకరమైన రూపం కలిగిన నువ్వు ఎవరో చెప్పు. పరమేశ్వరుడా, నీకు నా నమస్కారాలు అర్పిస్తున్నాను; నన్ను కరుణించు. అసలు జీవి అయిన నిన్ను తెలుసుకోవాలని నేను కోరుకుంటున్నాను. మీ పని తీరు నాకు నిజంగా తెలియదు.",
      "hi": "मुझे यह बताइये कि उग्ररूपवाले आप कौन हैं? हे देवताओंमें श्रेष्ठ ! आपको नमस्कार हो। आप प्रसन्न होइये। आदिरूप आपको मैं तत्त्वसे जानना चाहता हूँ; क्योंकि मैं आपकी प्रवृत्तिको नहीं जानता।",
      "sa": "आख्याहि मे को भवानुग्ररूपो\n\nनमोऽस्तु ते देववर प्रसीद।\n\nविज्ञातुमिच्छामि भवन्तमाद्यं\n\nन हि प्रजानामि तव प्रवृत्तिम्।।11.31।।",
      "gu": "અર્જુન ભગવાનને 'દેવોમાં શ્રેષ્ઠ' અને 'પ્રસન્ન થાઓ' જેવા શબ્દોથી સંબોધન કરે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
    },
    "hindiMeaning": "मुझे यह बताइये कि उग्ररूपवाले आप कौन हैं? हे देवताओंमें श्रेष्ठ ! आपको नमस्कार हो। आप प्रसन्न होइये। आदिरूप आपको मैं तत्त्वसे जानना चाहता हूँ; क्योंकि मैं आपकी प्रवृत्तिको नहीं जानता।",
