      "hi": "मैंने ऐसा रुप पहले कभी नहीं देखा। इस रूपको देखकर मैं हर्षित हो रहा हूँ और (साथ-ही-साथ) भयसे मेरा मन अत्यन्त व्यथित हो रहा है। अतः आप मुझे अपने उसी देवरूपको (सौम्य विष्णुरूपको)  दिखाइये। हे देवेश ! हे जगन्निवास ! आप प्रसन्न होइये।",
      "sa": "अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा\n\nभयेन च प्रव्यथितं मनो मे।\n\nतदेव मे दर्शय देव रूपं\n\nप्रसीद देवेश जगन्निवास।।11.45।।",
      "gu": "અર્જુન ભગવાન કૃષ્ણને વિનંતી કરે છે કે તેઓ પોતાનું ચતુર્ભુજ, દૈવી અને શાંતિદાયક રૂપ દર્શાવે. અર્જુન કહે છે કે તેમણે જે અદૃશ્યપૂર્વ વિશ્વરૂપ જોયું છે, તે અવ્યક્ત અને ભયજનક છે, તેથી તેઓ ભગવાન વિષ્ણુના પારંપરિક, દયાળુ અને આશ્વાસન આપતા રૂપને ફરીથી જોવામાં શાંતિ અનુભવે છે.",
      "ta": null,
      "kn": null,
      "ml": null,
      "mr": null,
      "bn": null,
      "pa": null,
      "or": null,
      "as": null,
      "ur": null,
      "ks": null,
      "kok": null,
      "mai": null,
      "mni": null,
      "ne": null,
      "brx": null,
      "sat": null,
      "sd": null,
      "doi": null
