      "te": "అర్జునుడు ఇలా అన్నాడు, \"ఓ కృష్ణా, ఈ నీ సున్నిత మానవ రూపాన్ని చూసి, ఇప్పుడు నేను స్వరపరిచాను మరియు నా స్వభావానికి తిరిగి వచ్చాను.\"",
      "hi": "अर्जुन बोले -- हे जनार्दन ! आपके इस सौम्य मनुष्यरूपको देखकर मैं इस समय स्थिरचित्त हो गया हूँ और अपनी स्वाभाविक स्थितिको प्राप्त हो गया हूँ।",
      "sa": "अर्जुन उवाच\n\nदृष्ट्वेदं मानुषं रूपं तवसौम्यं जनार्दन।\n\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः।।11.51।।",
      "gu": "અર્જુન અહીં શ્રીકૃષ્ણને 'જનાર્દન' તરીકે સંબોધિત કરે છે. અર્જુને શ્રીકૃષ્ણનું શાંત અને માનવરૂપ જોયું છે, જે તેમને શાંતિ અને સ્થિરતા આપે છે.",
